class LoungeAudio extends AudioWorkletProcessor{constructor(){super();this.l=new Float32Array(16384);this.r=new Float32Array(16384);this.rd=0;this.wr=0;this.n=0;this.ready=false;this.port.onmessage=({data:d})=>{if(d.clear){this.rd=this.wr=this.n=0;this.ready=false;return}if(this.n+d.l.length>4096){const drop=Math.min(this.n,this.n+d.l.length-2048);this.rd=(this.rd+drop)%16384;this.n-=drop}for(let i=0;i<d.l.length;i++){this.l[this.wr]=d.l[i];this.r[this.wr]=d.r[i];this.wr=(this.wr+1)%16384}this.n+=d.l.length;if(this.n>=1200)this.ready=true}}process(_,outputs){const o=outputs[0];if(!o||o.length<2)return true;for(let i=0;i<o[0].length;i++){if(this.ready&&this.n){o[0][i]=this.l[this.rd];o[1][i]=this.r[this.rd];this.rd=(this.rd+1)%16384;this.n--}else{o[0][i]=o[1][i]=0}}if(!this.n)this.ready=false;return true}}registerProcessor('lounge-audio',LoungeAudio);
